// Audio Manager handling generated sound effects from public/sounds/ and Web Audio fallback
class SoundEffects {
  constructor() {
    this.ctx = null;
    this.enabled = true;

    // Preload audio files generated by ffmpeg
    if (typeof window !== 'undefined') {
      try {
        const base = import.meta.env.BASE_URL || '/';
        const prefix = base.endsWith('/') ? base : `${base}/`;
        this.soundPrefix = prefix;
        this.matchAudio = new Audio(`${prefix}sounds/match.mp3`);
        this.winAudio = new Audio(`${prefix}sounds/win.mp3`);
        this.matchAudio.preload = 'auto';
        this.winAudio.preload = 'auto';
      } catch {
        this.matchAudio = null;
        this.winAudio = null;
      }
    }
  }

  init() {
    if (!this.ctx && typeof window !== 'undefined') {
      const AudioContext = window.AudioContext || window.webkitAudioContext;
      if (AudioContext) {
        this.ctx = new AudioContext();
      }
    }
    if (this.ctx && this.ctx.state === 'suspended') {
      this.ctx.resume();
    }
  }

  // Play flip card sound
  playFlip() {
    if (!this.enabled) return;
    this.init();
    if (!this.ctx) return;

    try {
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      const now = this.ctx.currentTime;

      osc.type = 'sine';
      osc.frequency.setValueAtTime(440, now);
      osc.frequency.exponentialRampToValueAtTime(720, now + 0.08);

      gain.gain.setValueAtTime(0.15, now);
      gain.gain.exponentialRampToValueAtTime(0.01, now + 0.08);

      osc.connect(gain);
      gain.connect(this.ctx.destination);

      osc.start(now);
      osc.stop(now + 0.09);
    } catch {
      // Audio fallback fail-safe
    }
  }

  // Play match sound (short "ding" generated with ffmpeg)
  playMatch() {
    if (!this.enabled) return;

    try {
      // Create clone to allow rapid repeated playback without clipping previous sounds
      const audio = this.matchAudio
        ? this.matchAudio.cloneNode()
        : new Audio(`${this.soundPrefix || '/'}sounds/match.mp3`);
      audio.volume = 0.85;
      const playPromise = audio.play();
      if (playPromise !== undefined) {
        playPromise.catch(() => {
          // Fallback to web audio synthesis if browser blocks unmuted direct audio
          this.playMatchSynth();
        });
      }
    } catch {
      this.playMatchSynth();
    }
  }

  playMatchSynth() {
    this.init();
    if (!this.ctx) return;
    try {
      const now = this.ctx.currentTime;
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(1174.66, now);
      gain.gain.setValueAtTime(0.2, now);
      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.35);
      osc.connect(gain);
      gain.connect(this.ctx.destination);
      osc.start(now);
      osc.stop(now + 0.36);
    } catch {}
  }

  // Play mismatch buzz sound
  playMismatch() {
    if (!this.enabled) return;
    this.init();
    if (!this.ctx) return;

    try {
      const now = this.ctx.currentTime;
      const notes = [293.66, 246.94]; // D4 -> B3
      notes.forEach((freq, index) => {
        const osc = this.ctx.createOscillator();
        const gain = this.ctx.createGain();
        const time = now + index * 0.1;

        osc.type = 'sawtooth';
        osc.frequency.setValueAtTime(freq, time);

        gain.gain.setValueAtTime(0.12, time);
        gain.gain.exponentialRampToValueAtTime(0.01, time + 0.12);

        osc.connect(gain);
        gain.connect(this.ctx.destination);

        osc.start(time);
        osc.stop(time + 0.13);
      });
    } catch {
      // Audio fallback fail-safe
    }
  }

  // Play victory melody (3 ascending notes generated with ffmpeg)
  playWin() {
    if (!this.enabled) return;

    try {
      const audio = this.winAudio
        ? this.winAudio.cloneNode()
        : new Audio(`${this.soundPrefix || '/'}sounds/win.mp3`);
      audio.volume = 0.9;
      const playPromise = audio.play();
      if (playPromise !== undefined) {
        playPromise.catch(() => {
          this.playWinSynth();
        });
      }
    } catch {
      this.playWinSynth();
    }
  }

  playWinSynth() {
    this.init();
    if (!this.ctx) return;
    try {
      const now = this.ctx.currentTime;
      const notes = [523.25, 659.25, 1046.50];
      notes.forEach((freq, idx) => {
        const osc = this.ctx.createOscillator();
        const gain = this.ctx.createGain();
        const start = now + idx * 0.18;
        const dur = idx === 2 ? 0.7 : 0.25;

        osc.type = 'sine';
        osc.frequency.setValueAtTime(freq, start);

        gain.gain.setValueAtTime(0.2, start);
        gain.gain.exponentialRampToValueAtTime(0.005, start + dur);

        osc.connect(gain);
        gain.connect(this.ctx.destination);

        osc.start(start);
        osc.stop(start + dur + 0.02);
      });
    } catch {}
  }

  playRestart() {
    if (!this.enabled) return;
    this.init();
    if (!this.ctx) return;

    try {
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      const now = this.ctx.currentTime;

      osc.type = 'sine';
      osc.frequency.setValueAtTime(300, now);
      osc.frequency.exponentialRampToValueAtTime(600, now + 0.15);

      gain.gain.setValueAtTime(0.18, now);
      gain.gain.exponentialRampToValueAtTime(0.01, now + 0.15);

      osc.connect(gain);
      gain.connect(this.ctx.destination);

      osc.start(now);
      osc.stop(now + 0.16);
    } catch {}
  }
}

export const sounds = new SoundEffects();
